def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, float(bid))

    yesterday_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 500:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev.get('bid', 0.0)))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    units = supply / WATER_REQ
    very_tight = units < 1.45
    tight = units < 1.7
    comfortable = units >= 1.9

    survival_mode = hp <= 3 or no_water >= 1
    danger_mode = hp <= 2 or no_water >= 2

    if danger_mode:
        base = DAILY_SALARY * 1.28
    elif survival_mode:
        base = DAILY_SALARY * 1.0
    elif very_tight:
        base = DAILY_SALARY * 0.82
    elif tight:
        base = DAILY_SALARY * 0.62
    elif comfortable:
        base = DAILY_SALARY * 0.38
    else:
        base = DAILY_SALARY * 0.5

    if highest_prev >= 120:
        if survival_mode or very_tight:
            base = max(base, min(150.0, highest_prev + 2.0))
        else:
            base = min(base, DAILY_SALARY * 0.42)
    elif highest_prev >= 80:
        if survival_mode:
            base = max(base, highest_prev + 1.5)
        else:
            base = max(base, avg_prev * 0.72)
    elif highest_prev > 0:
        if tight or survival_mode:
            base = max(base, highest_prev + 1.0)
        else:
            base = max(base, avg_prev * 0.9)

    if rich_count >= 1 and not survival_mode and not very_tight:
        base *= 0.88
    if desperate_count >= 2 and (tight or survival_mode):
        base *= 1.12

    if day >= 8 and hp >= 5 and no_water == 0 and not tight:
        base *= 0.9

    if budget < DAILY_SALARY:
        base = min(base, budget * 0.92)
    elif budget < 2 * DAILY_SALARY and not survival_mode:
        base = min(base, DAILY_SALARY * 0.72)

    bid = min(budget, max(0.0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # React to yesterday's bidding pressure: focus on highest previous bid among alive opponents.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: if supply is near max, we can afford lower bid; if near min, raise bid.
    # Normalize to [0,1] where 0 => MIN_SUPPLY, 1 => MAX_SUPPLY
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Baseline aggressiveness: Cindy bid ~124 avg and survived; match slightly below her typical pressure.
    # If highest_prev_bid was very high, increase bid; otherwise keep moderate.
    if highest_prev_bid >= DAILY_SALARY * 1.25:  # ~112.5
        base = DAILY_SALARY * 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.85:  # ~76.5
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # Adjust for my urgency.
    if my_hp <= 2:
        urgency = 1.35
    elif my_hp <= 4:
        urgency = 1.15
    else:
        urgency = 1.00

    if my_no_water_days >= 2:
        urgency *= 1.15

    # If supply is low, increase bid; if high, decrease.
    supply_factor = 0.95 + (1.0 - supply_norm) * 0.25  # low supply => up to ~1.2

    target_bid = base * urgency * supply_factor

    # Cap by budget and keep some reserve for later days.
    # Reserve more when HP is healthy.
    if my_hp >= 6:
        reserve_frac = 0.25
    elif my_hp >= 3:
        reserve_frac = 0.15
    else:
        reserve_frac = 0.05

    max_affordable = my_budget * (1.0 - reserve_frac)
    target_bid = min(target_bid, max_affordable)

    # Ensure non-negative and at least a minimal bid when budget allows.
    if target_bid < 0:
        target_bid = 0.0

    # If budget is extremely low, bid what you can.
    if my_budget <= 10:
        return min(my_budget, DAILY_SALARY * 0.2)

    # Final clamp to a reasonable range relative to DAILY_SALARY.
    lower = DAILY_SALARY * 0.25
    upper = DAILY_SALARY * 0.95
    target_bid = max(lower, min(upper, target_bid))

    return min(my_budget, target_bid)
